#include <stdio.h>

void show(const char *label, int value) {
    unsigned char x = (unsigned char)value;
    printf("%s = ", label);
    for (int i = 7; i >= 0; i--) {
        printf("%d", (x >> i) & 1);
    }
    printf("\n");
}

int main(void) {
    show("6", 6);
    show("3", 3);
    show("6 & 3", 6 & 3);
    show("6 | 3", 6 | 3);
    show("6 ^ 3", 6 ^ 3);
    return 0;
}

